  "recovered_c": "uint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len < 3) {\n    return VERA_ERR;\n  }\n\n  size_t i = 0;\n  while (i < len) {\n    uint32_t value = (uint32_t)in[i] << 24 | (uint32_t)in[i + 1] << 16 | (uint32_t)in[i + 2] << 8;\n    if ((len + 1) * len & 1) != 0 || arg != 0) {\n      value = ((len << 7) ^ value) * 0x2d6b + 0x3c71;\n      value = value >> 11 ^ value;\n    }\n\n    out[i * 2] = (uint8_t)(value >> 16);\n    out[i * 2 + 1] = (uint8_t)(value >> 8);\n\n    i += 3;\n  }\n\n  return len * 2;\n}"
